using Lou.Core;
using Lou.Rendering;
using Xunit;
using SkiaSharp;
namespace Lou.Tests;
public class CoreTests
{
    [Fact] public void Rotation_skips_disabled_pages_and_honors_duration(){var s=new Settings();s.Pages[1].Enabled=false;var scheduler=new PageScheduler();var now=DateTimeOffset.UtcNow;Assert.Equal(PageId.System,scheduler.Select(s,Snapshot.Empty,now));Assert.Equal(PageId.System,scheduler.Select(s,Snapshot.Empty,now.AddSeconds(14)));Assert.Equal(PageId.Music,scheduler.Select(s,Snapshot.Empty,now.AddSeconds(15)));}
    [Fact] public void Smart_gaming_preempts_music_but_respects_disabled_page(){var s=new Settings{Mode=RotationMode.Smart};var scheduler=new PageScheduler();Assert.Equal(PageId.Gaming,scheduler.Select(s,Snapshot.Simulation(),DateTimeOffset.Now));s.Pages.Single(p=>p.Id==PageId.Gaming).Enabled=false;Assert.NotEqual(PageId.Gaming,scheduler.Select(s,Snapshot.Simulation(),DateTimeOffset.Now.AddMinutes(1)));}
    [Fact] public void Fixed_page_remains_selected(){var s=new Settings{Mode=RotationMode.Fixed,FixedPage=PageId.Weather};Assert.Equal(PageId.Weather,new PageScheduler().Select(s,Snapshot.Simulation(),DateTimeOffset.Now));}
    [Fact] public void Missing_music_can_be_hidden(){var s=new Settings();s.Pages.Single(p=>p.Id==PageId.Music).HideUnavailable=true;var r=new PageScheduler();var now=DateTimeOffset.UtcNow;r.Select(s,Snapshot.Empty,now);r.Select(s,Snapshot.Empty,now.AddSeconds(15));Assert.Equal(PageId.Gaming,r.Select(s,Snapshot.Empty,now.AddSeconds(30)));}
    [Theory][InlineData(1920,462,462f/480)][InlineData(1920,468,468f/480)][InlineData(1920,480,1f)][InlineData(480,480,.25f)]public void Aspect_ratio_is_preserved(int w,int h,float expected){var fit=NeonRenderer.Fit(w,h);Assert.Equal(expected,fit.Scale,4);Assert.True(fit.X>=0&&fit.Y>=0);Assert.True(1920*fit.Scale<=w+.01&&480*fit.Scale<=h+.01);}
    [Fact] public void Missing_and_nonfinite_values_are_not_fake_numbers(){Assert.Equal("—",NeonRenderer.V(null,"%"));Assert.Equal("—",NeonRenderer.V(double.NaN,"%"));}
    [Fact] public void Configuration_validation_rejects_no_pages_bad_coordinates_and_schema(){var s=new Settings();s.Pages.ForEach(p=>p.Enabled=false);Assert.Throws<InvalidDataException>(s.Validate);s=new Settings{Latitude=double.NaN};Assert.Throws<InvalidDataException>(s.Validate);s=new Settings{Version=2};Assert.Throws<InvalidDataException>(s.Validate);}
    [Fact] public void Config_roundtrip_and_backup(){var root=Path.Combine(Path.GetTempPath(),"lou-test-"+Guid.NewGuid());var path=Path.Combine(root,"settings.json");var s=new Settings{Location="Test"};ConfigStore.Save(s,path);s.Location="Second";ConfigStore.Save(s,path);Assert.Equal("Second",ConfigStore.Load(path).Location);Assert.Equal("Test",ConfigStore.Load(path+".bak").Location);}
    [Fact] public void Night_wraps_midnight(){var s=new Settings();Assert.True(s.IsNight(DateTime.Today.AddHours(23)));Assert.True(s.IsNight(DateTime.Today.AddHours(3)));Assert.False(s.IsNight(DateTime.Today.AddHours(12)));}
    [Theory][InlineData(Transition.Slide)][InlineData(Transition.Glitch)][InlineData(Transition.Scanline)][InlineData(Transition.None)]public void Transition_completes_on_target_frame(Transition effect){using var a=new SKBitmap(40,10);using var b=new SKBitmap(40,10);a.Erase(SKColors.Red);b.Erase(SKColors.Blue);using var output=TransitionRenderer.Compose(a,b,1,effect);Assert.Equal(SKColors.Blue,output.GetPixel(20,5));}
    [Theory][InlineData(Transition.Slide)][InlineData(Transition.Glitch)][InlineData(Transition.Scanline)]public void Transition_starts_on_source_frame(Transition effect){using var a=new SKBitmap(40,10);using var b=new SKBitmap(40,10);a.Erase(SKColors.Red);b.Erase(SKColors.Blue);using var output=TransitionRenderer.Compose(a,b,0,effect);Assert.Equal(SKColors.Red,output.GetPixel(20,5));}
    [Theory][InlineData(PageId.System)][InlineData(PageId.Weather)][InlineData(PageId.Music)][InlineData(PageId.Gaming)][InlineData(PageId.Ambient)]public void Each_page_renders_missing_data_at_native_dimensions(PageId page){using var renderer=new NeonRenderer("missing-assets");var s=new Settings{Width=1920,Height=462};using var image=renderer.Render(page,Snapshot.Empty,s,DateTime.Now,0);Assert.Equal(1920,image.Width);Assert.Equal(462,image.Height);Assert.NotEqual(SKColors.Transparent,image.GetPixel(960,240));}
}
